#include "al_default_repo.h"
namespace al {
namespace art {
static void add(Geometry& g,Vec3 lo,Vec3 hi,const char* material){for(int a=0;a<3;a++)if(hi[a]-lo[a]<.001)return;g.brushes.push_back(box(lo,hi,material));}
static void light(Geometry& g,Vec3 p,int intensity){g.entities.push_back({{{"classname","light"},{"origin",brushio::vectorText(p)},{"light",std::to_string(intensity)}}});}
static void append(Geometry& a,const Geometry& b){a.brushes.insert(a.brushes.end(),b.brushes.begin(),b.brushes.end());a.entities.insert(a.entities.end(),b.entities.begin(),b.entities.end());}
}
Geometry corridorCell(const std::array<bool,6>& open){using namespace art;Geometry g;for(int x:{48,192})for(int y:{48,192})add(g,{double(x),double(y),16},{double(x+16),double(y+16),144},"al_trim");add(g,{48,48,0},{208,208,16},"al_floor");add(g,{48,48,144},{208,208,160},"al_ceiling");for(int d:{0,2,3,5}){int a=d==0||d==3?0:1,b=1-a;auto box2=[&](double a0,double a1,double b0,double b1,double z0,double z1,const char* m){Vec3 lo{},hi{};lo[a]=a0;hi[a]=a1;lo[b]=b0;hi[b]=b1;lo.z=z0;hi.z=z1;add(g,lo,hi,m);};bool pos=d>=3;if(open[d]){double low=pos?208:0,high=pos?256:48;box2(low,high,48,64,16,144,"al_wall");box2(low,high,192,208,16,144,"al_wall");box2(low,high,48,208,0,16,"al_floor");box2(low,high,48,208,144,160,"al_ceiling");}else box2(pos?192:48,pos?208:64,64,192,16,144,"al_wall");}return g;}
Geometry roomCell(const std::array<bool,6>& walls,const std::array<bool,6>& doors,bool floor,bool ceiling,double z0,double z1,double doorZ){using namespace art;Geometry g;if(floor)add(g,{0,0,0},{256,256,16},"al_floor");if(ceiling)add(g,{0,0,176},{256,256,192},"al_ceiling");for(int d:{0,2,3,5})if(walls[d]){int a=d==0||d==3?0:1,b=1-a;double low=b==1&&walls[2]?16:0,high=b==1&&walls[5]?240:256;auto wall=[&](double b0,double b1,double h0,double h1){Vec3 lo{},hi{};lo[a]=d>=3?240:0;hi[a]=lo[a]+16;lo[b]=b0;hi[b]=b1;lo.z=h0;hi.z=h1;add(g,lo,hi,"al_wall");};if(!doors[d])wall(low,high,z0,z1);else{wall(low,64,z0,z1);wall(192,high,z0,z1);wall(64,192,std::max(z0,doorZ+128),z1);wall(64,192,z0,std::min(z1,doorZ));}}return g;}
Geometry stairGeometry(){using namespace art;Geometry g;add(g,{0,0,0},{256,512,16},"al_floor");add(g,{0,0,368},{256,512,384},"al_ceiling");for(int x:{0,240})add(g,{double(x),0,16},{double(x+16),512,368},"al_wall");for(int y:{0,496}){add(g,{16,double(y),16},{64,double(y+16),368},"al_wall");add(g,{192,double(y),16},{240,double(y+16),368},"al_wall");if(y==0)add(g,{64,0,144},{192,16,368},"al_wall");else{add(g,{64,496,16},{192,512,208},"al_wall");add(g,{64,496,336},{192,512,368},"al_wall");}}
 for(int k=1;k<=12;k++)add(g,{16,64.+32*(k-1),16},{240,64.+32*k,16.+16*k},"al_stair");add(g,{16,448,16},{240,496,208},"al_stair");light(g,{128,256,300},250);return g;}
Geometry atriumGeometry(){using namespace art;Geometry g;add(g,{0,0,0},{512,512,16},"al_floor");add(g,{0,0,368},{512,512,384},"al_ceiling");auto wall=[&](int d,const std::vector<std::pair<double,double>>& openings){int a=d==0||d==3?0:1,b=1-a;double lo=b==1?16:0,hi=b==1?496:512;auto piece=[&](double b0,double b1,double z0,double z1){Vec3 low{},high{};low[a]=d>=3?496:0;high[a]=low[a]+16;low[b]=b0;high[b]=b1;low.z=z0;high.z=z1;add(g,low,high,"al_wall");};std::vector<double> cuts{lo,hi};for(auto o:openings){cuts.push_back(o.first);cuts.push_back(o.first+128);}std::sort(cuts.begin(),cuts.end());cuts.erase(std::unique(cuts.begin(),cuts.end()),cuts.end());for(size_t i=0;i+1<cuts.size();i++){bool door=false;double z=16;for(auto o:openings)if(cuts[i]>=o.first&&cuts[i+1]<=o.first+128){door=true;z=o.second;}if(door){piece(cuts[i],cuts[i+1],16,z);piece(cuts[i],cuts[i+1],z+128,368);}else piece(cuts[i],cuts[i+1],16,368);}};
 wall(2,{{64,16}});wall(3,{{64,16}});wall(5,{{320,16}});wall(0,{{64,208},{320,208}});add(g,{16,16,192},{112,496,208},"al_floor");add(g,{112,16,208},{120,496,248},"al_trim");light(g,{320,256,340},300);light(g,{320,256,120},250);return g;}
BigBlockAsset bigFromGeometry(Repo& repo,const Geometry& geometry,Int3 size,const std::string& uid,const std::string& name,const std::string& group,float weight){BigBlockAsset big;big.uid=uid;big.name=name;big.size=size;big.overrideGroup=big.overrideWeightGroup=true;big.group=big.weightGroup=group;big.actionsGroups={"Full Rotate On Z"};big.data.resize(volume(size));for(size_t i=0;i<volume(size);i++){auto p=position(i,size);auto lo=mul(vec(p),repo.cellSize);auto part=translateGeometry(clipGeometry(geometry,lo,lo+repo.cellSize),lo*-1);BlockAsset b;b.uid=uid+"_"+std::to_string(i);b.name=name+" part "+std::to_string(i);b.group=b.weightGroup=group;b.geometry=writeMap(part);b.variants[0].bigBlockUid=uid;b.variants[0].weight=weight;big.data[i]={{b.uid,0}};repo.blocks.push_back(b);}return big;}
Repo defaultRepo(){using namespace art;Repo r;r.uid="reyond-dungeon";r.name="Reyond Dungeon";r.useFilling=false;r.groups=r.weightGroups={"Corridors","Rooms","Vertical","Decor"};auto cell=[&](const char* uid,const char* group,std::initializer_list<int> sides,float weight,const char* actions,bool room){BlockAsset b;b.uid=uid;b.name=uid;b.group=b.weightGroup=group;if(actions&&*actions)b.actionsGroups={actions};std::array<bool,6> open{};for(int d:sides){open[d]=true;b.variants[0].sideIds[d]=1;}b.variants[0].weight=weight;std::array<bool,6> walls{};for(int d:{0,2,3,5})walls[d]=true;auto g=room?roomCell(walls,open):corridorCell(open);if(room){light(g,{128,128,150},250);b.hasSpawn=true;b.spawnPoint={128,160,40};}b.geometry=writeMap(g);r.blocks.push_back(b);};
 cell("corridor_straight","Corridors",{2,5},1,"Rotate On Z",false);cell("corridor_corner","Corridors",{2,3},.7f,"Full Rotate On Z",false);cell("corridor_t","Corridors",{2,3,0},.7f,"Full Rotate On Z",false);cell("corridor_cross","Corridors",{0,2,3,5},.15f,"",false);cell("corridor_deadend","Corridors",{2},.02f,"Full Rotate On Z",false);cell("chamber_end","Rooms",{2},.15f,"Full Rotate On Z",true);cell("chamber_corner","Rooms",{2,3},.3f,"Full Rotate On Z",true);
 Geometry hall;for(int y=0;y<2;y++)for(int x=0;x<2;x++){std::array<bool,6> walls{},doors{};walls[0]=x==0;walls[3]=x==1;walls[2]=y==0;walls[5]=y==1;int door=x==0&&y==0?2:x==1&&y==0?3:x==1&&y==1?5:0;doors[door]=true;auto g=roomCell(walls,doors);Vec3 corner{x==0?224.:0.,y==0?224.:0.,16};add(g,corner,corner+Vec3{32,32,160},"al_trim");light(g,{128,128,150},200);append(hall,translateGeometry(g,{256.*x,256.*y,0}));}
 auto big=bigFromGeometry(r,hall,{2,2,1},"hall","hall_2x2","Rooms",4.32f);for(int i=0;i<4;i++){int door=i==0?2:i==1?3:i==3?5:0;variant(r,big.data[i][0])->sideIds[door]=1;}r.bigBlocks.push_back(big);
 big=bigFromGeometry(r,stairGeometry(),{1,2,2},"stair","stair_straight","Vertical",8.64f);variant(r,big.data[0][0])->sideIds[2]=1;variant(r,big.data[3][0])->sideIds[5]=1;r.bigBlocks.push_back(big);
 big=bigFromGeometry(r,atriumGeometry(),{2,2,2},"atrium","atrium_2x2x2","Vertical",6);variant(r,big.data[0][0])->sideIds[2]=1;variant(r,big.data[1][0])->sideIds[3]=1;variant(r,big.data[3][0])->sideIds[5]=1;variant(r,big.data[4][0])->sideIds[0]=1;variant(r,big.data[6][0])->sideIds[0]=1;for(size_t c=0;c<big.data.size();c++){auto bp=block(r,big.data[c][0].blockUid);bp->walkableSides=uint8_t(63&~(1<<1)&~(1<<4));if(c>=4&&(c%2)==1)bp->walkable=false;}r.bigBlocks.push_back(big);
 auto decor=[&](const char* uid,const char* dep,float weight,bool crate){auto base=block(r,dep);BlockAsset b;b.uid=uid;b.name=uid;b.group=b.weightGroup="Decor";b.actionsGroups=base->actionsGroups;b.variants[0].sideIds=base->variants[0].sideIds;b.variants[0].layerSettings.layer=1;b.variants[0].layerSettings.dependencies={{dep,0}};b.variants[0].weight=weight;b.walkable=false;Geometry g;if(crate){add(g,{176,176,16},{224,224,64},"al_trim");add(g,{184,184,64},{216,216,96},"al_trim");}else{add(g,{120,112,136},{136,144,144},"al_trim");light(g,{128,128,120},180);}b.geometry=writeMap(g);r.blocks.push_back(b);};decor("corridor_lamp","corridor_straight",.5f,false);decor("corridor_lamp_t","corridor_t",.8f,false);decor("chamber_crates","chamber_end",.6f,true);integrity(r);return r;}
Builder defaultBuilder(const Repo& r,bool empty){Builder b;b.uid=empty?"builder-empty":"dungeon";b.name=empty?"New empty builder":"Dungeon";b.repoUid=r.uid;resize(b,{0,0,0},empty?Int3{5,5,5}:Int3{8,8,3},2);b.selection=empty?Bounds3i{{},{1,1,1}}:Bounds3i{{2,2,0},{6,6,3}};if(!empty){for(auto& side:b.boundary)side.groups={"Solid"};b.groupsWeights={{"Empty",true,.3f},{"Solid",true,.05f}};b.rebuildBottomLayers=true;}return b;}
}
